// ============================ Helper Comparators ============================

// Lexicographic comparison: first by value, then by remoteness.
static int CompareByValueThenRemoteness(Value v1, int r1, Value v2, int r2) {
    if (v1 != v2) return (v1 > v2) ? 1 : -1;
    if (r1 != r2) return (r1 > r2) ? 1 : -1;
    return 0;
}

// Reversed comparison: lower value-remoteness pairs are considered "greater".
static int CompareReversed(Value v1, int r1, Value v2, int r2) {
    return -CompareByValueThenRemoteness(v1, r1, v2, r2);
}

