// =========================== AtomicRecordMaximize ===========================

// Verifies that a strictly greater candidate replaces the current record.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeReplacesWhenCandidateGreater) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kLose, 0);

    bool replaced =
        AtomicRecordMaximize(&ar, kWin, 10, CompareByValueThenRemoteness);

    EXPECT_TRUE(replaced) << "Should return true when candidate is greater.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kWin)
        << "Value should be updated to the candidate's value.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 10)
        << "Remoteness should be updated to the candidate's remoteness.";
}

// Verifies that a strictly smaller candidate does not replace the record.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeKeepsWhenCandidateSmaller) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kWin, 10);

    bool replaced =
        AtomicRecordMaximize(&ar, kLose, 0, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced) << "Should return false when candidate is smaller.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kWin)
        << "Value should remain unchanged.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 10)
        << "Remoteness should remain unchanged.";
}

// Verifies that an equal candidate does not replace the current record.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeKeepsWhenEqual) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kTie, 5);

    bool replaced =
        AtomicRecordMaximize(&ar, kTie, 5, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced) << "Should return false when candidate is equal.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kTie)
        << "Value should remain unchanged.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 5)
        << "Remoteness should remain unchanged.";
}

// Verifies that a candidate with the same value but higher remoteness replaces.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeReplacesOnRemotenessAlone) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kWin, 3);

    bool replaced =
        AtomicRecordMaximize(&ar, kWin, 7, CompareByValueThenRemoteness);

    EXPECT_TRUE(replaced)
        << "Should return true when candidate has higher remoteness.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kWin) << "Value should remain kWin.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 7)
        << "Remoteness should be updated to 7.";
}

// Verifies that a candidate with the same value but lower remoteness does not
// replace.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeKeepsOnRemotenessAlone) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kWin, 7);

    bool replaced =
        AtomicRecordMaximize(&ar, kWin, 3, CompareByValueThenRemoteness);

    EXPECT_FALSE(replaced)
        << "Should return false when candidate has lower remoteness.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kWin) << "Value should remain kWin.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 7)
        << "Remoteness should remain 7.";
}

// Verifies that Maximize correctly delegates ordering to the comparator.
TEST(ArrayDbAtomicRecordArrayTest, MaximizeWithAlternativeComparator) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kWin, 10);

    // With CompareReversed, (kLose, 0) is considered "greater" than (kWin, 10).
    bool replaced = AtomicRecordMaximize(&ar, kLose, 0, CompareReversed);

    EXPECT_TRUE(replaced)
        << "Should return true when candidate is greater under the reversed "
           "comparator.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kLose)
        << "Value should be updated to kLose under the reversed comparator.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 0)
        << "Remoteness should be updated to 0 under the reversed comparator.";
}

