// Verifies that decrementing is a no-op when value is kWin.
TEST(ArrayDbAtomicRecordArrayTest, DecrementWhenNotUndecidedWin) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kWin, 10);

    int result = AtomicRecordDecrementNumUndecidedChildren(&ar);

    EXPECT_EQ(result, 0) << "Should return 0 when value is not kUndecided.";
    EXPECT_EQ(AtomicRecordGetValue(&ar), kWin) << "Value should remain kWin.";
    EXPECT_EQ(AtomicRecordGetRemoteness(&ar), 10)
        << "Remoteness should remain unchanged.";
}

// Verifies that successive decrements correctly drain the count to zero.
TEST(ArrayDbAtomicRecordArrayTest, DecrementSuccessivelyToZero) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kUndecided, 3);

    EXPECT_EQ(AtomicRecordDecrementNumUndecidedChildren(&ar), 3)
        << "First decrement should return 3.";
    EXPECT_EQ(AtomicRecordDecrementNumUndecidedChildren(&ar), 2)
        << "Second decrement should return 2.";
    EXPECT_EQ(AtomicRecordDecrementNumUndecidedChildren(&ar), 1)
        << "Third decrement should return 1.";
    EXPECT_EQ(AtomicRecordDecrementNumUndecidedChildren(&ar), 0)
        << "Fourth decrement should return 0 (count was already zero).";
    EXPECT_EQ(AtomicRecordGetNumUndecidedChildren(&ar), 0)
        << "Final count should be 0.";
}

