// ======================== Cross-function Integration ========================

// Verifies the interplay between SetValueRemoteness and
// GetNumUndecidedChildren.
TEST(ArrayDbAtomicRecordArrayTest,
     SetValueRemotenessThenGetNumUndecidedChildren) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kUndecided, 3);

    EXPECT_EQ(AtomicRecordGetNumUndecidedChildren(&ar), 3)
        << "NumUndecidedChildren should match remoteness when value is "
           "kUndecided.";

    AtomicRecordSetValue(&ar, kWin);

    EXPECT_EQ(AtomicRecordGetNumUndecidedChildren(&ar), 0)
        << "NumUndecidedChildren should be 0 once value is no longer "
           "kUndecided.";
}

// Verifies that decrementing followed by clearing works correctly together.
TEST(ArrayDbAtomicRecordArrayTest, DecrementThenClear) {
    AtomicRecord ar;
    AtmoicRecordInit(&ar, kUndecided, 5);

    int after_dec = AtomicRecordDecrementNumUndecidedChildren(&ar);
    EXPECT_EQ(after_dec, 5) << "Decrement should return the old count of 5.";
    EXPECT_EQ(AtomicRecordGetNumUndecidedChildren(&ar), 4)
        << "Count should be 4 after one decrement.";

    int after_clear = AtomicRecordClearNumUndecidedChildren(&ar);
    EXPECT_EQ(after_clear, 4) << "Clear should return the old count of 4.";
    EXPECT_EQ(AtomicRecordGetNumUndecidedChildren(&ar), 0)
        << "Count should be 0 after clearing.";
}

